function star(g,x,y,r,color='#efd294'){let p=[];for(let i=0;i<10;i++){let a=i*Math.PI/5-Math.PI/2,s=i%2?r*.46:r;p.push([x+Math.cos(a)*s,y+Math.sin(a)*s]);}P(g,'M'+p.map(p=>p.join(' ')).join('L')+'Z',color,[x-r,y-r,r*2,r*2],55);}
function panel(g,x,y,w,h,c){P(g,`M${x} ${y}L${x+w} ${y-2} ${x+w+2} ${y+h} ${x-2} ${y+h+1}Z`,c,[x-3,y-4,w+7,h+7],Math.round(w*h/60));}
function gem(g,x,y,r,c='#baa1ca'){P(g,`M${x} ${y-r}L${x+r*.75} ${y} ${x} ${y+r} ${x-r*.75} ${y}Z`,c,[x-r,y-r,r*2,r*2],35);L(g,[[x,y-r],[x,y+r]],'#f4e4de',1.2);}
function crescent(g,x,y,r,c){P(g,`M${x+r*.5} ${y-r}Q${x-r*1.2} ${y-r} ${x-r} ${y+r*.15}Q${x-r*.6} ${y+r*1.2} ${x+r*.6} ${y+r*.65}Q${x-r*.2} ${y+r*.5} ${x-r*.3} ${y-r*.1}Q${x-r*.3} ${y-r*.6} ${x+r*.5} ${y-r}Z`,c,[x-r*1.2,y-r,r*2,r*2.2],120);}
